def _llm_addon_enabled(cfg: IntelligenceConfig) -> bool:
    mode = (cfg.intent_context.llm_mode or "auto").lower()
    key = cfg.reasoner.openai_api_key
    if mode == "rules":
        return False
    if mode == "llm":
        return bool(key)
    return bool(key)

